import { chromium } from 'playwright-core';
const browser = await chromium.launch();

async function layoutAt(width) {
  const page = await browser.newPage({ viewport: { width, height: 800 } });
  await page.goto('http://127.0.0.1:4173/');
  const itemsBox = await page.locator('.items').boundingBox();
  const summaryBox = await page.locator('.summary').boundingBox();
  const sideBySide = summaryBox.x >= itemsBox.x + itemsBox.width - 5; // summary starts at/after items end
  const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
  const clientWidth = await page.evaluate(() => document.documentElement.clientWidth);
  const checkoutBox = await page.locator('.checkout').boundingBox();
  await page.close();
  return { width, sideBySide, scrollWidth, clientWidth, hScroll: scrollWidth > clientWidth, checkoutBox };
}

for (const w of [767, 768, 769, 375]) {
  console.log(w, JSON.stringify(await layoutAt(w)));
}
await browser.close();
EOF
